//! Closed candidate CQ14: total at most three cultists, at most three regions.
use crate::{catalog,engine::RuleResult,model::*,rules::*};
use serde::{Serialize,Deserialize};
use crate::bq095::Destination;
use std::collections::{BTreeMap,BTreeSet};
pub(crate) const ID:&str="CQ14";pub(crate) const KEY:&str="cq14-summon";
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]
pub struct Draft{pub actor:usize,pub turn:u32,pub card:Card,pub grave:Option<Destination>,pub regions:Option<Vec<(usize,String,u32)>>}
#[derive(Clone,Debug,Serialize,Deserialize)]#[serde(deny_unknown_fields)]
pub struct GravePayment{pub zone:Destination,pub character:Card,pub discarded:Card}
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
fn region()->TargetSlotSpec{target(Zone::Region,EntityKind::Any,Relation::Any,Range::Anywhere)}
pub(crate) fn definition()->Definition{let mut a=ability(KEY,"盖罗涅的召令：至多三个地区生成总计至多三个横置邪教徒",Timing::Standard,vec![],vec![],vec![Op::CQ14Summon{counts:vec![],grave:false}],None);a.play_only=true;with_abilities(vec![a])}
fn owns(o:&Op)->bool{match o{Op::CQ14Summon{..}=>true,Op::ForEachLivingPlayer(v)|Op::ForEachLivingPlayerFromActor(v)=>v.iter().any(owns),Op::IfTargetExhausted{exhausted,ready,..}=>owns(exhausted)||owns(ready),_=>false}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("cq14-")||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(owns)}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{if id!=ID||!same(a,&definition().abilities[0]){return Err("召令须保留原标准事务程序".into())}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("召令定义不能移植或改写".into())}Ok(())}
impl Game{
 fn cq14_character(&self,actor:usize)->Option<Card>{self.regions.iter().filter(|r|!r.vacant).flat_map(|r|&r.cards).find(|c|c.controller==actor&&!c.face_down&&catalog::card(&c.definition).kind=="character"&&matches!(catalog::card(&c.definition).name.as_str(),"盖罗涅"|"深渊惧影盖罗涅")).cloned()}
 fn cq14_red(&self,actor:usize)->Vec<Card>{self.players[actor].hand.iter().filter(|c|catalog::card(&c.definition).color=="红").cloned().collect()}
 fn cq14_draft(&self,d:&Draft)->RuleResult<()>{if d.actor>=self.players.len()||d.turn!=self.turn||d.card.definition!=ID||d.card.controller!=d.actor||d.card.face_down||self.status!="playing"||self.players[d.actor].eliminated||self.priority_team!=self.team(d.actor)||!self.stack.is_empty()||self.window!=Some(Window::Action(self.team(d.actor)))||!self.loyalty(d.actor,ID)||self.resources(d.actor)<self.effective_cost(d.actor,&d.card)||self.xq22_spell_banned(){return Err("召令原标准行动或费用资格已变化".into())}self.msbq02_allow_play(d.actor,&d.card)?;let live=if let Some(zone)=&d.grave{if !same(zone,&self.bq095_own_reference(&d.card))||self.cq14_character(d.actor).is_none()||self.cq14_red(d.actor).is_empty(){return Err("墓地召令需要实际盖罗涅及红色手牌".into())}self.bq095_self_grave_sources(d.actor).into_iter().find(|c|c.id==d.card.id)}else{self.players[d.actor].hand.iter().find(|c|c.id==d.card.id)};if live.is_none_or(|c|!same(c,&d.card)){return Err("召令实际来源或区域已变化".into())}if let Some(rs)=&d.regions{if d.grave.is_none()||rs.len()>3||rs.iter().map(|v|v.0).collect::<BTreeSet<_>>().len()!=rs.len()||rs.iter().any(|(r,id,n)|*n==0||*n>3||!self.region_live(*r)||self.regions[*r].card.id!=*id)||rs.iter().map(|v|v.2).sum::<u32>()>3{return Err("召令分配已失效".into())}}Ok(())}
 fn cq14_options(&self,d:&Draft)->Vec<ChoiceOption>{if d.regions.is_some(){return self.cq14_red(d.actor).into_iter().map(|c|ChoiceOption{id:c.id.clone(),label:catalog::card(&c.definition).name.clone(),card:Some(self.card_view(&c,d.actor,None,Some("hand")))}).collect()}(0..self.regions.len()).filter(|r|self.region_live(*r)).flat_map(|r|(0..3).map(move|n|ChoiceOption{id:format!("{r}:{n}"),label:format!("地区{}生成邪教徒{}",r+1,n+1),card:None})).collect()}
 fn cq14_prompt(&mut self,d:Draft)->RuleResult<()>{self.cq14_draft(&d)?;let red=d.regions.is_some();let opts=self.cq14_options(&d);self.choice(d.actor,if red{"cq14-red"}else{"cq14-regions"},if red{"召令：弃一张红色手牌"}else{"召令：分配至多三个邪教徒"}.into(),opts,if red{1}else{0},if red{1}else{3},None,ChoiceResolution::CQ14Draft{draft:Box::new(d)});Ok(())}
 pub(crate) fn cq14_begin(&mut self,actor:usize,c:Card,grave:bool,a:&Action)->RuleResult<()>{if *a!=(Action{card_id:Some(c.id.clone()),..Action::new("play")}){return Err("召令须经原地区及额外费用选择".into())}let zone=grave.then(||self.bq095_own_reference(&c));self.cq14_prompt(Draft{actor,turn:self.turn,card:c,grave:zone,regions:None})}
 pub(crate) fn cq14_choose(&mut self,mut d:Draft,seat:usize,a:&Action,ids:&[String])->RuleResult<()>{self.cq14_draft(&d)?;let opts=self.cq14_options(&d);if seat!=d.actor||*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")})||ids.iter().collect::<BTreeSet<_>>().len()!=ids.len()||ids.iter().any(|id|!opts.iter().any(|o|o.id==*id)){return Err("召令只接受原玩家合法分配或弃牌".into())}if d.regions.is_none(){if ids.len()>3{return Err("召令总计最多三个邪教徒".into())}let mut counts=BTreeMap::new();for id in ids{let r=id.split(':').next().unwrap().parse::<usize>().map_err(|_|"地区无效")?;*counts.entry(r).or_insert(0u32)+=1;}let rs=counts.into_iter().map(|(r,n)|(r,self.regions[r].card.id.clone(),n)).collect();if d.grave.is_some(){d.regions=Some(rs);return self.cq14_prompt(d)}return self.cq14_cast(d,rs,None)}if ids.len()!=1{return Err("墓地召令必须弃一张红色牌".into())}let discarded=self.cq14_red(seat).into_iter().find(|c|c.id==ids[0]).ok_or("原红牌已离手")?;let rs=d.regions.take().unwrap();self.cq14_cast(d,rs,Some(discarded))}
 fn cq14_cast(&mut self,d:Draft,rs:Vec<(usize,String,u32)>,discarded:Option<Card>)->RuleResult<()>{let source=self.source_snapshot(&d.card,None);let mut paid=self.pay_printed(d.actor,&d.card,true)?;if let Some(zone)=&d.grave{let character=self.cq14_character(d.actor).ok_or("原盖罗涅已离场")?;let discarded=discarded.ok_or("缺红牌费用")?;self.discard_hand_card(d.actor,&discarded.id)?;paid.push(PaidCost::CQ14Grave(Box::new(GravePayment{zone:zone.clone(),character,discarded})));}let c=if d.grave.is_some(){self.bq095_take_reference(&d.card,&d.card.id)?}else{self.remove_hand(d.actor,&d.card.id)?};let c=self.fresh(c);let spec=definition().abilities.remove(0);let targets=rs.iter().map(|(r,id,_)|{let name=format!("region:{r}");BoundTarget{region_instance:Some(id.clone()),public:self.public_target(d.actor,&source,&region(),&name),id:name,spec:region()}}).collect();let mut f=self.make_frame(d.actor,source,&spec,targets,paid,None);f.steps=vec![Step{context:d.actor,op:Op::CQ14Summon{counts:rs.iter().map(|r|r.2).collect(),grave:d.grave.is_some()}}];self.dispatch_frame(f,spec.label,Some(c),spec.response_policy);Ok(())}
 pub(crate) fn cq14_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if f.source.card.definition!=ID&&!f.ability_key.starts_with("cq14-")&&!f.steps.iter().any(|s|owns(&s.op)){return Ok(())}self.validate_resource_frame(f)?;let [Step{context,op:Op::CQ14Summon{counts,grave}}]=f.steps.as_slice()else{return Err("召令须保留实际生成程序".into())};let c=&f.source.card;if c.definition!=ID||c.face_down||c.controller!=f.actor||c.owner>=self.players.len()||f.actor>=self.players.len()||*context!=f.actor||f.ability_key!=KEY||f.source.region.is_some()||f.source.source_region_instance.is_some()||f.source.play_source.is_some()||f.source.attachment_host_instance.is_some()||f.chosen_region.is_some()||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||counts.len()!=f.targets.len()||counts.len()>3||counts.iter().any(|n|*n==0||*n>3)||counts.iter().sum::<u32>()>3||f.targets.iter().map(|t|&t.id).collect::<BTreeSet<_>>().len()!=f.targets.len(){return Err("召令来源或总生成数量损坏".into())}self.mobility_immutable_identity(c)?;for t in &f.targets{let r=t.id.strip_prefix("region:").and_then(|s|s.parse::<usize>().ok()).filter(|r|*r<self.regions.len()).ok_or("召令原目标非普通地区")?;if !same(&t.spec,&region())||t.region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||t.public.region!=Some(r)||t.public.instance_id!=t.id{return Err("召令原地区绑定损坏".into())}}match f.already_paid.as_slice(){[PaidCost::Assets(_)] if !grave=>(),[PaidCost::Assets(_),PaidCost::CQ14Grave(p)] if *grave=>{if p.character.controller!=f.actor||p.character.face_down||!matches!(catalog::card(&p.character.definition).name.as_str(),"盖罗涅"|"深渊惧影盖罗涅")||p.discarded.controller!=f.actor||catalog::card(&p.discarded.definition).color!="红"||p.discarded.id==c.id||!matches!(&p.zone,Destination::Graveyard(s)if *s==f.actor)&&!matches!(&p.zone,Destination::Headquarters(id)if self.mystic_instance_valid(id)){return Err("墓地召令原许可或弃红收据损坏".into())}self.mobility_immutable_identity(&p.character)?;self.mobility_immutable_identity(&p.discarded)?;},_=>return Err("召令费用收据损坏".into())}if f.money_units(0)>3{return Err("召令资产费用损坏".into())}Ok(())}
 pub(crate) fn cq14_step(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.cq14_frame(f)?;if f.cursor!=1{return Err("召令须经原结算入口".into())}let Op::CQ14Summon{counts,..}=&f.steps[0].op else{unreachable!()};for(t,n)in f.targets.iter().zip(counts){if self.valid_bound_target(f.actor,&f.source,t){let r=t.public.region.unwrap();for _ in 0..*n{let mut c=self.make_generated(crate::generated::GeneratedKind::Cultist,f.actor)?;c.exhausted=true;let id=c.id.clone();self.regions[r].cards.push(c);self.enter_triggers(f.actor,"TK008",&id,false);}}}Ok(())}
 pub(crate) fn validate_cq14_state(&self)->RuleResult<()>{let mut seen=BTreeSet::new();for i in &self.stack{if i.card.as_ref().is_some_and(|c|c.definition==ID)||i.frame.as_ref().is_some_and(|f|f.source.card.definition==ID||f.ability_key==KEY){let f=i.frame.as_ref().ok_or("召令实际事务缺帧")?;self.cq14_frame(f)?;if !seen.insert(&f.frame_id)||i.id!=f.frame_id||i.controller!=f.actor||i.reveal||i.deploy_region.is_some()||f.cursor!=0||i.card.as_ref().is_none_or(|c|!self.pack_a_transaction_matches(f,c)){return Err("召令实际事务外壳损坏".into())}}}for e in &self.effects{match e{Effect::Frame{frame:f}if f.source.card.definition==ID||f.ability_key==KEY=>return Err("召令单步不能脱离原事务".into()),Effect::Declare{declaration:d}if d.source.card.definition==ID||related(&d.ability)=>return Err("召令没有触发声明".into()),_=>()}}if let Some(p)=&self.pending{if let ChoiceResolution::CQ14Draft{draft:d}=&p.resolution{self.cq14_draft(d)?;let red=d.regions.is_some();let expected=Choice{id:p.choice.id.clone(),kind:if red{"cq14-red"}else{"cq14-regions"}.into(),title:if red{"召令：弃一张红色手牌"}else{"召令：分配至多三个邪教徒"}.into(),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(d.actor),options:self.cq14_options(d),preview_cards:vec![],min:Some(if red{1}else{0}),max:Some(if red{1}else{3}),amount:None,allow_decline:Some(!red)};if p.seat!=d.actor||!self.mystic_instance_valid(&p.choice.id)||!same(&p.choice,&expected){return Err("召令原待选损坏".into())}}}Ok(())}
}
